# 其中$CONFIG是一个JavaScript对象
mytool --config=$CONFIG --name="test"

# Becomes after parsing with rehydration:
# 经过解析和重新水合后变成：
['mytool', '--config', {setting: true, values: [1,2,3]}, '--name', 'test']

