  largeProjectState,
  10,     // 从深度10开始
  50_000  // 上下文限制50KB
);

// 遥测错误报告
const errorContext = normalizeToSize(
  applicationState,
  5,       // 合理的深度
  10_000   // 错误报告限制10KB
);

