### 1、将中国标准时间转为 yyyymmdd

```javascript
export function getYYYYMMDD(string) {
	const d = new Date(string);
	const datetime =
		d.getFullYear() +
		"-" +
		(d.getMonth() + 1) +
		"-" +
		d.getDate() +
		" " +
		d.getHours() +
		":" +
		d.getMinutes() +
		":" +
		d.getSeconds();

	return datetime;
}
```

### 2、去除字符串内所有空格

```javascript
export function RemoveAllSpaces(string) {
	return string.replace(new RegExp(" ", "gm"), "");
}
