```less
// index.less
@import "/src/static/baseFontSize";

.startup {
  width: 100vw;
  height: 100vh;
  background-image: linear-gradient(180deg, #282c60 0%, #0e173e 66%);
  position: absolute;
  top: 0;
  left: 0;
  z-index: 800;
