											this.showProgressMask = false;
											that.$bus.$emit("ImportSuccessful");
											clearInterval(a);
										}
									})
									.catch((err_) => {
										console.log(err_);
									});
							}, 1000);
						}
					})
					.catch((err) => {
						console.log(err);
						loading.close();
					});
