			return {
				percentage: 0,
				showProgressMask: false,
			};
		},
		methods: {
      // 自定义上传方法
			uploadSectionFile(content) {
				let that = this;
				const loading = this.$loading({
					lock: true,
					text: "文件上传中",
					spinner: "el-icon-loading",
					background: "rgba(0, 0, 0, 0.7)",
				});
				uploadFile_1(content, this.uploadURL, this.projectId)
					.then((res) => {
						console.log(res);
						loading.close();
						if (res.transactionId) {
							loading.close();
							this.cancel();
							this.showProgressMask = true;
							let a = setInterval(() => {
								getProcess("/import/progress", {
									data: {
										transactionId: res.transactionId,
										type: this.type,
									},
								})
									.then((data_) => {
										console.log(data_);
										if (data_.status == 0) {
											this.percentage = Number.parseFloat(((data_.complete / data_.total) * 100).toFixed(2));
											console.log(this.percentage, "this.percentage");
											if (this.percentage >= 100) {
												console.log("完毕");
												clearInterval(a);
												this.$message.success("导入成功");
												that.$bus.$emit("ImportSuccessful");
												this.showProgressMask = false;
											}
										} else if (data_.status == 1 && data_.complete == data_.total) {
											this.percentage = 100;
											this.$message.success("导入成功");
											that.$bus.$emit("ImportSuccessful");
											this.showProgressMask = false;
											clearInterval(a);
										} else {
											this.$message.error("导入失败");
											this.showProgressMask = false;
											that.$bus.$emit("ImportSuccessful");
											clearInterval(a);
										}
									})
									.catch((err_) => {
										console.log(err_);
									});
							}, 1000);
						}
					})
					.catch((err) => {
						console.log(err);
						loading.close();
					});
			},
			cancel() {
				// console.log(this.type)
				this.$emit("update:show-local-import", false);
			},
		},
		watch: {
			showProgressMask() {
				if (!this.showProgressMask) {
					this.percentage = 0;
				}
			},
		},
	};
